    );
  }

  if (ctx.retryCodes && ctx.retryCodes.length > 0) {
    lines.push("", "NOUVEL ESSAI", "Ta réponse précédente a été refusée. Corrige-la :");
    for (const code of [...new Set(ctx.retryCodes)]) lines.push(`- ${correctionFor(code, p)}`);
