  new RegExp(
    `\\b(?:${SELF}) (?:(?:la|ici|here|bien|vraiment|really|aqui|aca|qui|hier|vraie?|real|echt|vera|vero) )*(?:pour de vrai|en vrai de vrai|for real|de verdad|de verdade|per davvero)\\b`,
