  "pas|not|no|nao|non|kein|keine|keinen|keiner|nicht|ni|jamais|never|nunca|isn t|aren t|ain t|wasn t";
const NEG_ADV =
  "(?:(?:du tout|at all|vraiment|really|realmente|wirklich|davvero|even|meme|simplement|einfach|nem|nemmeno) )?";
const NEG_ART =
